22	final class Journal {
23	  private static final String TAG = "Journal";
24	
25	  // You must restart the app after enabling these logs for the change to take affect.
26	  // We cache isLoggable to avoid the performance hit of checking repeatedly.
27	  private static final boolean LOG_VERBOSE = Log.isLoggable(TAG, Log.VERBOSE);
28	  private static final boolean LOG_DEBUG = Log.isLoggable(TAG, Log.DEBUG);
29	  private static final boolean LOG_WARN = Log.isLoggable(TAG, Log.WARN);
30	
31	  private static final String ROW_ID = "rowid";
32	  private static final String WHERE_KEY = JournalTable.Columns.KEY + " = ?";
33	  private static final String WHERE_PENDING_DELETE = JournalTable.Columns.PENDING_DELETE + " != 0";
34	
35	  // If a commit fails (renameTo returns false) and then the app dies before the commit is aborted,
36	  // we will end up with a temp file and an entry in the journal for a key. New puts for that key
37	  // should be able to complete successfully, so we use insert or replace to allow the entry to be
38	  // updated. We don't normally expect to be replacing entries.
39	  private static final String INSERT_NEW_KEY_SQL =
40	      "INSERT OR REPLACE INTO "
41	          + JournalTable.TABLE_NAME
42	          + "("
43	          + JournalTable.Columns.KEY
44	          + ", "
45	          + JournalTable.Columns.LAST_MODIFIED_TIME
46	          + ", "
47	          + JournalTable.Columns.SIZE
48	          + ") VALUES (?, ?, ?)";
49	  private static final int INSERT_NEW_KEY_KEY_IDX = 1;
50	  private static final int INSERT_NEW_KEY_MODIFIED_TIME_IDX = 2;
51	  private static final int INSERT_NEW_KEY_SIZE_IDX = 3;
52	
53	  private static final String CONTAINS_KEY_SQL =
54	      "SELECT COUNT(*) FROM " + JournalTable.TABLE_NAME + " WHERE " + WHERE_KEY;
55	  private static final int CONTAINS_KEY_KEY_IDX = 1;
56	
57	  private static final String SELECT_ENTRY_SIZE_NOT_PENDING_SQL =
58	      "SELECT "
59	          + JournalTable.Columns.SIZE
60	          + " FROM "
61	          + JournalTable.TABLE_NAME
62	          + " WHERE "
63	          + WHERE_KEY
64	          + " AND "
65	          + JournalTable.Columns.PENDING_DELETE
66	          + " = 0";
67	  private static final int SELECT_ENTRY_SIZE_NOT_PENDING_KEY_IDX = 1;
68	
69	  private static final String DELETE_ENTRY_SQL =
70	      "DELETE FROM " + JournalTable.TABLE_NAME + " WHERE " + WHERE_KEY;
71	  private static final int DELETE_ENTRY_KEY_IDX = 1;
72	
73	  private static final String[] LRU_PROJECTION =
74	      new String[] {JournalTable.Columns.KEY, JournalTable.Columns.SIZE};
75	  private static final String[] STALE_PROJECTION =
76	      new String[] {JournalTable.Columns.KEY, JournalTable.Columns.LAST_MODIFIED_TIME, ROW_ID};
77	  private static final String LRU_WHERE = JournalTable.Columns.PENDING_DELETE + " = 0";
78	  private static final String STALE_WHERE =
79	      ROW_ID + " > ? AND " + JournalTable.Columns.LAST_MODIFIED_TIME + " < ?";
80	  // rowid comes from https://www.sqlite.org/rowidtable.html. See b/206890186.
81	  private static final String LRU_ORDER_BY =
82	      JournalTable.Columns.LAST_MODIFIED_TIME + " ASC, rowid ASC";
83	  private static final String STALE_ORDER_BY = ROW_ID + " ASC";
84	  private static final int LRU_BATCH_SIZE = 25;
85	  private static final int STALE_BATCH_SIZE = 25;
86	
87	  private static final String SUM_SIZE_WHERE_NOT_PENDING_DELETE =
88	      "SELECT SUM("
89	          + JournalTable.Columns.SIZE
90	          + ") FROM "
91	          + JournalTable.TABLE_NAME
92	          + " WHERE "
93	          + JournalTable.Columns.PENDING_DELETE
94	          + " = 0";
95	
96	  private static final String[] PENDING_DELETE_PROJECTION = new String[] {JournalTable.Columns.KEY};
97	
98	  private static final int DELETE_BATCH_SIZE = 200;
99	
100	  private final DiskCacheDbHelper dbHelper;
101	  private final SqliteStatementPool statementPool;
102	  private final Clock clock;
103	  private final Handler updateTimesHandler;
104	  private final SizeJournal sizeJournal;
105	
106	  Journal(
107	      DiskCacheDbHelper dbHelper,
108	      Looper workThreadLooper,
109	      int updateModifiedTimeBatchSize,
110	      Clock clock) {
111	    this.dbHelper = dbHelper;
112	    this.sizeJournal = new SizeJournal(dbHelper);
113	    statementPool = new SqliteStatementPool(dbHelper);
114	    this.clock = clock;
115	
116	    updateTimesHandler =
117	        new Handler(
118	            workThreadLooper,
119	            new UpdateTimesCallback(dbHelper, updateModifiedTimeBatchSize, clock));
120	  }
