130	  void clear() {
131	    SQLiteDatabase db = dbHelper.getWritableDatabase();
132	    db.beginTransactionNonExclusive();
133	    try {
134	      db.delete(JournalTable.TABLE_NAME, null /*whereClause*/, null /*whereArgs*/);
135	      sizeJournal.clearInTransaction();
136	      db.setTransactionSuccessful();
137	    } finally {
138	      db.endTransaction();
139	    }
140	  }
