146	  void put(String key, long sizeBytes) {
147	    Preconditions.checkArgument(!TextUtils.isEmpty(key));
148	    SQLiteDatabase db = dbHelper.getWritableDatabase();
149	    SQLiteStatement insertStatement = statementPool.obtain(INSERT_NEW_KEY_SQL);
150	    insertStatement.bindString(INSERT_NEW_KEY_KEY_IDX, key);
151	    insertStatement.bindLong(INSERT_NEW_KEY_MODIFIED_TIME_IDX, clock.currentTimeMillis());
152	    insertStatement.bindLong(INSERT_NEW_KEY_SIZE_IDX, sizeBytes);
153	
154	    SizeSQLiteTransactionListener sizeListener = sizeJournal.prepareSizeTransaction();
155	    db.beginTransactionWithListenerNonExclusive(sizeListener);
156	    try {
157	      insertStatement.executeInsert();
158	      sizeJournal.incrementSizeInTransaction(sizeListener, sizeBytes);
159	      db.setTransactionSuccessful();
160	    } finally {
161	      db.endTransaction();
162	      statementPool.offer(INSERT_NEW_KEY_SQL, insertStatement);
163	      sizeJournal.endSizeTransaction(sizeListener);
164	    }
165	  }
166	
167	  List<String> getPendingDeleteKeys() {
168	    List<String> result = new ArrayList<>();
169	    SQLiteDatabase db = dbHelper.getReadableDatabase();
170	    Cursor cursor =
171	        db.query(
172	            JournalTable.TABLE_NAME,
173	            PENDING_DELETE_PROJECTION,
174	            WHERE_PENDING_DELETE,
175	            null /*selectionArgs*/,
176	            null /*groupBy*/,
177	            null /*having*/,
178	            null /*orderBy*/);
179	    try {
180	      while (cursor.moveToNext()) {
181	        String key = cursor.getString(cursor.getColumnIndexOrThrow(JournalTable.Columns.KEY));
182	        if (TextUtils.isEmpty(key)) {
183	          if (LOG_WARN) {
184	            Log.w(TAG, "Found empty or null key: %s, skipping delete: " + key);
185	          }
186	        } else {
187	          result.add(key);
188	        }
189	      }
190	    } finally {
191	      cursor.close();
192	    }
193	    return result;
194	  }
