196	  List<String> getLeastRecentlyUsed(long targetByteCount) {
197	    SQLiteDatabase db = dbHelper.getReadableDatabase();
198	    List<String> keys = new ArrayList<>();
199	    long currentByteCount = 0;
200	    int currentOffset = 0;
201	    boolean isOutOfEntries = false;
202	    while (!isOutOfEntries && currentByteCount < targetByteCount) {
203	      Cursor cursor =
204	          db.query(
205	              JournalTable.TABLE_NAME,
206	              LRU_PROJECTION,
207	              LRU_WHERE,
208	              null /*selectionArgs*/,
209	              null /*groupBy*/,
210	              null /*having*/,
211	              LRU_ORDER_BY,
212	              currentOffset + ", " + LRU_BATCH_SIZE);
213	      try {
214	        int keyIdx = cursor.getColumnIndexOrThrow(JournalTable.Columns.KEY);
215	        int sizeIdx = cursor.getColumnIndexOrThrow(JournalTable.Columns.SIZE);
216	        while (cursor.moveToNext() && currentByteCount < targetByteCount) {
217	          String key = cursor.getString(keyIdx);
218	          keys.add(key);
219	
220	          long sizeBytes = cursor.getLong(sizeIdx);
221	          currentByteCount += sizeBytes;
222	        }
223	        isOutOfEntries = cursor.getCount() < LRU_BATCH_SIZE;
224	      } finally {
225	        cursor.close();
226	      }
227	      currentOffset += LRU_BATCH_SIZE;
228	    }
229	
230	    // TODO(judds): for a sufficiently large file or small cache size and a failed attempt to commit
231	    // a put, this can happen because our journal size will temporarily not match our File size.
232	    // If this becomes an issue, we can safely just clear the cache here instead of throwing because
233	    // we were about to delete all the files anyway.
234	    if (isOutOfEntries && currentByteCount < targetByteCount) {
235	      throw new IllegalStateException(
236	          "Size mismatch"
237	              + ", expected to be able to evict at least "
238	              + targetByteCount
239	              + " bytes"
240	              + ", but only found "
241	              + currentByteCount
242	              + " bytes worth of entries!");
243	    }
244	
245	    return keys;
246	  }
