248	  List<String> getStaleEntries(long staleTimeThresholdMs) {
249	    SQLiteDatabase db = dbHelper.getReadableDatabase();
250	    List<String> keys = new ArrayList<>();
251	    long currentRowId = 0L;
252	    boolean isOutOfEntries = false;
253	    while (!isOutOfEntries) {
254	      try (Cursor cursor =
255	          db.query(
256	              JournalTable.TABLE_NAME,
257	              STALE_PROJECTION,
258	              LRU_WHERE + " AND " + STALE_WHERE,
259	              new String[] {String.valueOf(currentRowId), String.valueOf(staleTimeThresholdMs)},
260	              null /*groupBy*/,
261	              null /*having*/,
262	              STALE_ORDER_BY,
263	              String.valueOf(STALE_BATCH_SIZE))) {
264	        int keyIdx = cursor.getColumnIndexOrThrow(JournalTable.Columns.KEY);
265	        while (cursor.moveToNext()) {
266	          keys.add(cursor.getString(keyIdx));
267	          currentRowId = cursor.getLong(cursor.getColumnIndexOrThrow(ROW_ID));
268	        }
269	        isOutOfEntries = cursor.getCount() < STALE_BATCH_SIZE;
270	      }
271	    }
272	    return keys;
273	  }
