275	  /**
276	   * Removes the pending entry from the journal for the given key and returns the size in bytes of
277	   * the entry, or returns 0 if no such entry exists.
278	   */
279	  void abortPut(String key) {
280	    SQLiteDatabase db = dbHelper.getWritableDatabase();
281	    SQLiteStatement containsKeyStatement = statementPool.obtain(CONTAINS_KEY_SQL);
282	    containsKeyStatement.bindString(CONTAINS_KEY_KEY_IDX, key);
283	    SQLiteStatement selectNotPendingSizeStatement =
284	        statementPool.obtain(SELECT_ENTRY_SIZE_NOT_PENDING_SQL);
285	    selectNotPendingSizeStatement.bindString(SELECT_ENTRY_SIZE_NOT_PENDING_KEY_IDX, key);
286	    SQLiteStatement deleteEntryStatement = statementPool.obtain(DELETE_ENTRY_SQL);
287	    deleteEntryStatement.bindString(DELETE_ENTRY_KEY_IDX, key);
288	
289	    SizeSQLiteTransactionListener sizeListener = sizeJournal.prepareSizeTransaction();
290	    db.beginTransactionWithListenerNonExclusive(sizeListener);
291	    try {
292	      // We may be asked to abort a put that failed before the entry was updated, so we will
293	      // occasionally fail to find the entry here.
294	      boolean isKeyPresent = 0 != containsKeyStatement.simpleQueryForLong();
295	      if (!isKeyPresent) {
296	        return;
297	      }
298	      long entrySize;
299	      try {
300	        entrySize = selectNotPendingSizeStatement.simpleQueryForLong();
301	      } catch (SQLiteDoneException e) {
302	        // No row found for this key that is not pending delete.
303	        entrySize = 0;
304	      }
305	      int deleted = deleteEntryStatement.executeUpdateDelete();
306	      if (deleted != 1) {
307	        throw new IllegalStateException(
308	            "Failed to delete entry"
309	                + ", key: "
310	                + key
311	                + ", size: "
312	                + entrySize
313	                + ", actually deleted: "
314	                + deleted);
315	      } else {
316	        // If the item is pending delete its size is 0 here - skip decrementing.
317	        if (entrySize != 0) {
318	          sizeJournal.decrementSizeInTransaction(sizeListener, entrySize);
319	        }
320	      }
321	      db.setTransactionSuccessful();
322	    } finally {
323	      db.endTransaction();
324	      statementPool.offer(CONTAINS_KEY_SQL, containsKeyStatement);
325	      statementPool.offer(SELECT_ENTRY_SIZE_NOT_PENDING_SQL, selectNotPendingSizeStatement);
326	      statementPool.offer(DELETE_ENTRY_SQL, deleteEntryStatement);
327	      sizeJournal.endSizeTransaction(sizeListener);
328	    }
329	  }
330	
331	  void delete(List<String> keys) {
332	    SQLiteDatabase db = dbHelper.getWritableDatabase();
333	    for (int startPosition = 0; startPosition < keys.size(); startPosition += DELETE_BATCH_SIZE) {
334	      int endPosition = Math.min(keys.size(), startPosition + DELETE_BATCH_SIZE);
335	      List<String> batch = keys.subList(startPosition, endPosition);
336	      int batchSize = batch.size();
337	      if (batchSize == 0) {
338	        if (LOG_WARN) {
339	          Log.w(
340	              TAG,
341	              "Unexpectedly 0 sized batch between: "
342	                  + startPosition
343	                  + " and endPosition: "
344	                  + endPosition);
345	        }
346	        continue;
347	      }
348	      String[] keysToDelete = batch.toArray(new String[batchSize]);
349	      db.beginTransactionNonExclusive();
350	      try {
351	        int deleted =
352	            db.delete(JournalTable.TABLE_NAME, buildKeySelectionSet(batchSize), keysToDelete);
353	        if (deleted != keysToDelete.length && LOG_WARN) {
354	          Log.w(
355	              TAG,
356	              "Failed to delete all expected entries"
357	                  + ", expected: "
358	                  + keysToDelete.length
359	                  + ", deleted: "
360	                  + deleted);
361	        }
362	        db.setTransactionSuccessful();
363	      } finally {
364	        db.endTransaction();
365	      }
366	    }
367	  }
368	
369	  private static String buildKeySelectionSet(int count) {
370	    Preconditions.checkArgument(count > 0);
371	    String prefix = " IN(";
372	    String postfix = "?)";
373	    // (?,?,?), so 2 characters per item, except for the last one which is one character.
374	    int commaSeparatedCount = count - 1;
375	    StringBuilder sb =
376	        new StringBuilder(
377	                JournalTable.Columns.KEY.length()
378	                    + prefix.length()
379	                    + (2 * commaSeparatedCount)
380	                    + postfix.length())
381	            .append(JournalTable.Columns.KEY)
382	            .append(prefix);
383	    for (int i = 0; i < commaSeparatedCount; i++) {
384	      sb.append("?,");
385	    }
386	    return sb.append(postfix).toString();
387	  }
388	
389	  void markPendingDelete(List<String> keys) {
390	    ContentValues values = new ContentValues();
391	    values.put(JournalTable.Columns.PENDING_DELETE, 1);
392	    SQLiteDatabase db = dbHelper.getWritableDatabase();
393	
394	    for (int startPosition = 0; startPosition < keys.size(); startPosition += DELETE_BATCH_SIZE) {
395	      int endPosition = Math.min(keys.size(), startPosition + DELETE_BATCH_SIZE);
396	      List<String> batch = keys.subList(startPosition, endPosition);
397	      int batchSize = batch.size();
398	
399	      String[] keysToDelete = batch.toArray(new String[batchSize]);
400	      String keySelectionSet = buildKeySelectionSet(batchSize);
401	      SizeSQLiteTransactionListener sizeListener = sizeJournal.prepareSizeTransaction();
402	      db.beginTransactionWithListenerNonExclusive(sizeListener);
403	      try {
404	        long sumOfSizesOfNewlyPendingEntries =
405	            DatabaseUtils.longForQuery(
406	                db, SUM_SIZE_WHERE_NOT_PENDING_DELETE + " AND " + keySelectionSet, keysToDelete);
407	        sizeJournal.decrementSizeInTransaction(sizeListener, sumOfSizesOfNewlyPendingEntries);
408	        db.update(JournalTable.TABLE_NAME, values, keySelectionSet, keysToDelete);
409	        db.setTransactionSuccessful();
410	      } finally {
411	        db.endTransaction();
412	        sizeJournal.endSizeTransaction(sizeListener);
413	      }
414	    }
415	  }
416	
417	  private static class UpdateTimesCallback implements Handler.Callback {
418	    private final SQLiteOpenHelper dbHelper;
419	    private final int updateModifiedTimeBatchSize;
420	    private final List<String> keysToUpdate;
421	    private final String batchUpdatedModifiedTimeSql;
422	    private final Clock clock;
423	
424	    private SQLiteStatement sqlStatement;
425	
426	    UpdateTimesCallback(SQLiteOpenHelper dbHelper, int updateModifiedTimeBatchSize, Clock clock) {
427	      this.clock = clock;
428	      Preconditions.checkArgument(updateModifiedTimeBatchSize > 0);
429	      this.dbHelper = dbHelper;
430	      this.updateModifiedTimeBatchSize = updateModifiedTimeBatchSize;
431	      keysToUpdate = new ArrayList<>(updateModifiedTimeBatchSize);
432	
433	      batchUpdatedModifiedTimeSql =
434	          "UPDATE "
435	              + JournalTable.TABLE_NAME
436	              + " SET "
437	              + JournalTable.Columns.LAST_MODIFIED_TIME
438	              + " = ?"
439	              + " WHERE "
440	              + buildKeySelectionSet(updateModifiedTimeBatchSize);
441	    }
442	
443	    private SQLiteStatement getSqlStatement() {
444	      if (sqlStatement == null) {
445	        sqlStatement = dbHelper.getWritableDatabase().compileStatement(batchUpdatedModifiedTimeSql);
446	      }
447	      return sqlStatement;
448	    }
449	
450	    private void updateTimes() {
451	      long startTime = clock.currentTimeMillis();
452	      SQLiteDatabase db = dbHelper.getWritableDatabase();
453	      SQLiteStatement statement = getSqlStatement();
454	      long modifiedTime = clock.currentTimeMillis();
455	      statement.bindLong(1, modifiedTime);
456	      int size = keysToUpdate.size();
457	      for (int i = 0; i < size; i++) {
458	        String key = keysToUpdate.get(i);
459	        // 1 indexed, with the modified time as the first argument.
460	        statement.bindString(i + 2, key);
461	      }
462	      db.beginTransactionNonExclusive();
463	      try {
464	        int updated = statement.executeUpdateDelete();
465	        if (updated != updateModifiedTimeBatchSize && LOG_DEBUG) {
466	          Set<String> uniqueKeys = new HashSet<>(keysToUpdate);
467	          // This can happen in one of two cases:
468	          // 1. Files are deleted out from under us (by the system), triggering a cache rebuild.
469	          // 2. The corresponding entries are evicted while they're in the get queue.
470	          Log.d(
471	              TAG,
472	              "Failed to update modified time for all rows"
473	                  + ", time: "
474	                  + modifiedTime
475	                  + ", expected: "
476	                  + updateModifiedTimeBatchSize
477	                  + ", actually updated: "
478	                  + updated
479	                  + ", unique keys: "
480	                  + uniqueKeys.size());
481	        }
482	        db.setTransactionSuccessful();
483	      } finally {
484	        db.endTransaction();
485	      }
486	
487	      if (LOG_VERBOSE) {
488	        Log.v(
489	            TAG,
490	            "Completed update times with "
491	                + keysToUpdate.size()
492	                + " updates in "
493	                + (clock.currentTimeMillis() - startTime));
494	      }
495	    }
496	
497	    @Override
498	    public boolean handleMessage(Message msg) {
499	      if (msg.what != MessageIds.ADD_LAST_MODIFIED_KEY) {
500	        return false;
501	      }
502	      String updatedKey = (String) msg.obj;
503	      if (!keysToUpdate.contains(updatedKey)) {
504	        keysToUpdate.add(updatedKey);
505	      }
506	      if (keysToUpdate.size() == updateModifiedTimeBatchSize) {
507	        updateTimes();
508	        keysToUpdate.clear();
509	      }
510	
511	      return true;
512	    }
513	  }
514	}
