16	/**
17	 * An Lru disk cache that stores each entry as a single File and uses a SQL based journal to track
18	 * sizes and eviction order.
19	 *
20	 * <p>Operations are not guaranteed and will silently fail in unexpected cases.
21	 *
22	 * <p>The size of the cache is approximate and will be exceeded for short periods of time. Failure
23	 * cases may leave behind temporary files that should be cleaned up in the future when the cache is
24	 * re-opened or when operations are attempted again.
25	 *
26	 * <p>This class is thread safe and may be accessed from multiple threads simultaneously.
27	 */
28	final class JournaledLruDiskCache {
29	  private static final String TAG = "DiskCache";
30	  private static final String CANARY_FILE_NAME = "cache_canary";
31	  // You must restart the app after enabling these logs for the change to take affect.
32	  // We cache isLoggable to avoid the performance hit of checking repeatedly.
33	  private static final boolean LOG_WARN = Log.isLoggable(TAG, Log.WARN);
34	  private static final boolean LOG_VERBOSE = Log.isLoggable(TAG, Log.VERBOSE);
35	  // The fraction of the maximum byte size of the cache we will allow the cache to go over before
36	  // triggering an eviction.
37	  private static final float DEFAULT_EVICTION_SLOP_MULTIPLIER = 0.05f;
38	  // The number of items we will queue to update the date modified time of in batches.
39	  private static final int DEFAULT_UPDATE_MODIFIED_TIME_BATCH_SIZE = 20;
40	
41	  static final String TEMP_FILE_INDICATOR = ".tmp";
42	
43	  private final File cacheDirectory;
44	  private final FileSystem fileSystem;
45	  private final Journal journal;
46	  // We use this File to determine if the system has wiped out our cache directory, which it may do
47	  // at any time. If the File is not present, then either we've never opened the cache for the given
48	  // directory before, or the cache was wiped.
49	  private final File canaryFile;
50	  private final EvictionManager evictionManager;
51	  private final RecoveryManager recoveryManager;
52	  private final EntryCache entries = new EntryCache();
53	
54	  private volatile boolean isOpen;
55	
56	  /**
57	   * @param cacheDirectory The directory in which the cache should store its files (Warning: the
58	   *     cache will delete all Files in the given directory. The directory should not be used to
59	   *     store any other content).
60	   * @param maximumSizeBytes The target maximum size in bytes. The cache size may briefly exceed
61	   *     this size by up to around 25mb depending on the size, thread scheduling, and the number of
62	   *     failed requests.
63	   */
64	  JournaledLruDiskCache(
65	      File cacheDirectory,
66	      DiskCacheDbHelper diskCacheDbHelper,
67	      long maximumSizeBytes,
68	      long staleEvictionThresholdMs,
69	      Clock clock) {
70	    this(
71	        cacheDirectory,
72	        diskCacheDbHelper,
73	        new FileSystem() {},
74	        maximumSizeBytes,
75	        getBackgroundLooper(),
76	        DEFAULT_EVICTION_SLOP_MULTIPLIER,
77	        DEFAULT_UPDATE_MODIFIED_TIME_BATCH_SIZE,
78	        staleEvictionThresholdMs,
79	        clock);
80	  }
81	
82	  @VisibleForTesting
83	  JournaledLruDiskCache(
84	      File cacheDirectory,
85	      DiskCacheDbHelper diskCacheDbHelper,
86	      FileSystem fileSystem,
87	      long maximumSizeBytes,
88	      Looper workLooper,
89	      float slopMultiplier,
90	      int updateModifiedTimeBatchSize,
91	      long staleEvictionThresholdMs,
92	      Clock clock) {
93	    Preconditions.checkArgument(
94	        updateModifiedTimeBatchSize >= 1, "updated modified time batch size must be >= 1");
95	    this.cacheDirectory = cacheDirectory;
96	    this.fileSystem = fileSystem;
97	
