200	  List<String> delete(List<String> keys) {
201	    journal.markPendingDelete(keys);
202	    List<String> successfullyDeleted = new ArrayList<>(keys.size());
203	    for (String key : keys) {
204	      EntryCache.Entry entry = entries.get(key);
205	      entry.acquireWriteLock();
206	      try {
207	        File file = getCacheFile(key);
208	        if (fileSystem.delete(file)) {
209	          successfullyDeleted.add(key);
210	        } else if (LOG_WARN) {
211	          Log.w(TAG, "Failed to delete file: " + file);
212	        }
213	        entry.setNotPresent();
214	      } finally {
215	        entry.releaseWriteLock();
216	      }
217	    }
218	    journal.delete(successfullyDeleted);
219	    return successfullyDeleted;
220	  }
