222	  /**
223	   * Returns a File committed previously for the given key, or {@code null} if no such File exists.
224	   *
225	   * <p>If a write is in progress but not yet committed for the given key, this method will return
226	   * {@code null} immediately, just as if the key were simply not present.
227	   */
228	  public File get(String key) {
229	    long startTime = getLogTime();
230	    openIfNotOpen();
231	    final File result;
232	    EntryCache.Entry entry = entries.get(key);
233	    entry.acquireReadLock();
234	    try {
235	      if (entry.isStateKnown()) {
236	        result = entry.isPresent() ? entry.getFile() : null;
237	      } else {
238	        File cacheFile = getCacheFile(key);
239	        if (fileSystem.exists(cacheFile)) {
240	          entry.setPresent(cacheFile);
241	          result = cacheFile;
242	        } else {
243	          entry.setNotPresent();
244	          result = null;
245	        }
246	      }
247	      if (result != null) {
248	        journal.get(key);
249	      }
250	
251	      if (LOG_VERBOSE) {
252	        Log.v(TAG, "Completed get in: " + getElapsedTime(startTime) + ", key: " + key);
253	      }
254	    } finally {
255	      entry.releaseReadLock();
256	    }
257	
258	    return result;
259	  }
