261	  /**
262	   * Starts a put for the given key and returns a temporary {@link File} to which the caller can
263	   * write data, or {@code null} if an edit is already in progress for the given Key, or if a
264	   * committed entry already exists for the given key.
265	   *
266	   * <p>Callers should call {@link #commitPut(String, File)} with the given key and the {@link File}
267	   * returned from this method after they finish writing data to make the data they have written
268	   * available to calls to {@link #get(String)}. If an error occurs while writing data, callers can
269	   * omit calling {@link #commitPut(String, File)} and use {@link #abortPutIfNotCommitted(String,
270	   * File)} to cleanup any partial {@link File Files}.
271	   *
272	   * <p>Callers must call {@link #abortPutIfNotCommitted(String, File)} regardless of whether or not
273	   * their write succeeds. The expected pattern is as follows:
274	   *
275	   * <pre>{@code
276	   * File tempFile = cache.beginPut(key);
277	   * try {
278	   *   if (tempFile != null && writeToFile(someData, tempFile)) {
279	   *    cache.commitPut(key, tempFile);
280	   *   }
281	   * } finally {
282	   *   cache.abortIfNotCommitted(key, tempFile);
283	   * }
284	   * }</pre>
285	   *
286	   * <p>Until the caller calls {@link #abortPutIfNotCommitted(String, File)}, a lock is held that
287	   * will block future calls to this method for the given key.
288	   *
289	   * <p>The returned {@link File} may contain partial data if a previous write to this key failed.
290	   * Callers should not assume it is safe to append to the File without first clearing it.
291	   */
292	  @Nullable
293	  public File beginPut(String key) {
294	    long startTime = getLogTime();
295	    openIfNotOpen();
296	    verifyCanaryOrClear();
297	    EntryCache.Entry entry = entries.get(key);
298	    entry.acquireWriteLock();
299	
300	    File permanentFile = getCacheFile(key);
301	    if (fileSystem.exists(permanentFile)) {
302	      return null;
303	    }
304	
305	    File result = getTempFile(key);
306	    if (LOG_VERBOSE) {
307	      Log.v(TAG, "Completed begin put in: " + getElapsedTime(startTime) + ", key: " + key);
308	    }
309	    return result;
310	  }
311	
312	  /**
313	   * Updates the size of the cache based on the data in the given temporary file and renames the
314	   * given temporary File to its permanent equivalent and makes it available to calls from {@link
315	   * #get(String)}.
316	   *
317	   * <p>The given {@link File} must be a {@link File} returned from {@link #get(String)} for the
318	   * given key. No validation is performed to verify either that the given {@link File} is a
319	   * legitimate temporary file from this cache or that the given {@link File} matches the given key.
320	   *
321	   * <p>It is possible this commit may fail silently, there is no guarantee that the data in the
322	   * given {@link File} will actually be available from {@link #get(String)}} when this method
323	   * completes. In practice commits should fail rarely unless insufficient storage is available or
324	   * the cache's directory or files are manipulated by a third party.
325	   *
326	   * <p>If the commit does fail, it will do so in one of two ways:
327	   *
328	   * <ul>
329	   *   <li>Prior to or while writing the entry to the journal
330	   *   <li>After writing the entry to the journal prior to or while renaming the temporary file to
331	   *       the permanent file.
332	   * </ul>
333	   *
334	   * If the commit fails prior to writing the entry to the journal, the dangling temporary File will
335	   * be found during recovery and deleted. If the commit fails after writing the entry to the
336	   * journal, the temporary file will be found during recovery and deleted and the corresponding
337	   * journal entry will also be deleted. The absence of a temporary File for a given key is assumed
338	   * to mean that either no entry exists, or the entry is committed and may be read.
339	   *
340	   * @throws IllegalStateException If this method wasn't preceded by a call to {@link
341	   *     #beginPut(String)} for the given key.
342	   */
343	  public void commitPut(String key, File temp) {
344	    long startTime = getLogTime();
345	
346	    long totalBytesAdded = fileSystem.length(temp);
347	    journal.put(key, totalBytesAdded);
348	
349	    if (LOG_VERBOSE) {
350	      Log.v(TAG, "Completed insertIntoDb in: " + getElapsedTime(startTime));
351	    }
352	
353	    long startRenameTime = getLogTime();
354	    File permanentFile = getCacheFile(key);
355	
356	    boolean isRenameSuccessful = fileSystem.rename(temp, permanentFile);
357	    // If we fail to rename the file, we will try to recover in our next recovery phase.
358	    if (isRenameSuccessful) {
359	      if (LOG_VERBOSE) {
360	        Log.v(TAG, "Successfully renamed in: " + getElapsedTime(startRenameTime));
361	      }
362	      EntryCache.Entry entry = entries.get(key);
363	      entry.setPresent(permanentFile);
364	    } else if (LOG_WARN) {
365	      Log.w(TAG, "Failed to rename file" + ", from: " + temp + ", to: " + permanentFile);
366	    }
367	
368	    evictionManager.maybeScheduleEviction();
369	
370	    if (LOG_VERBOSE) {
371	      Log.v(
372	          TAG,
373	          "Completed commitPut in: "
374	              + getElapsedTime(startTime)
375	              + ", current size: "
376	              + journal.getCurrentSizeBytes()
377	              + ", key: "
378	              + key);
379	    }
380	  }
381	
382	  /**
383	   * Releases the write lock for the given key and, if the write was not committed, cleans up the
384	   * given temporary File and the corresponding journal entry for the given Key.
385	   *
386	   * <p>A write is assumed to have not been committed if the given temporary File still exists.
387	   */
388	  public void abortPutIfNotCommitted(String key, File temp) {
389	    try {
390	      // If the temporary File still exists, we haven't committed. If it doesn't exist, we either
391	      // didn't start writing and have nothing to roll back, or we finished writing and finished
392	      // the rename so the edit is committed.
393	      if (temp != null && fileSystem.delete(temp)) {
394	        journal.abortPut(key);
395	        EntryCache.Entry entry = entries.get(key);
396	        entry.setUnknown();
397	      }
398	    } finally {
399	      EntryCache.Entry entry = entries.get(key);
400	      entry.releaseWriteLock();
401	    }
402	  }
403	
404	  void recoverPartialWrite(File temp) {
405	    String key = keyFromFile(temp);
406	    EntryCache.Entry entry = entries.get(key);
407	    entry.acquireWriteLock();
408	    try {
409	      // Try to delete the temporary file, if it fails, we will try again in the next recovery
410	      // phase.
411	      boolean deleted = temp.delete();
412	      if (!deleted) {
413	        if (LOG_WARN) {
414	          Log.w(TAG, "Failed to cleanup in progress write: " + temp);
415	        }
416	        // The write lock prevents us from directly racing with an in progress write. However when
417	        // the write lock is released, we will get to run. If the write completed successfully,
418	        // the
419	        // temp file will no longer exist, but the entry will. We do not want to delete the entry
420	        // just because we happened to try to run recovery during the write.
421	        return;
422	      }
423	      delete(key);
424	    } finally {
425	      entry.releaseWriteLock();
426	    }
427	  }
428	
429	  private String keyFromFile(File file) {
430	    String name = file.getName();
431	    final String key;
432	    if (name.endsWith(TEMP_FILE_INDICATOR)) {
433	      key = name.substring(0, name.length() - TEMP_FILE_INDICATOR.length());
434	    } else {
435	      key = name;
436	    }
437	    return key;
438	  }
