27	/**
28	 * Ensures that two simultaneous requests for exactly the same url make only a single http request.
29	 *
30	 * <p>Requests are started by Glide on multiple threads in a thread pool. An arbitrary number of
31	 * threads may attempt to start or cancel requests for one or more urls at once. Our goal is to
32	 * ensure:
33	 * <li>
34	 *
35	 *     <ul>
36	 *       A new request is made to cronet if a url is requested and no cronet request for that url is
37	 *       in progress
38	 * </ul>
39	 *
40	 * <ul>
41	 *   Subsequent requests for in progress urls do not make new requests to cronet, but are notified
42	 *   when the existing cronet request completes.
43	 * </ul>
44	 *
45	 * <ul>
46	 *   Cancelling a single request does not cancel the cronet request if multiple requests for the url
47	 *   have been made, but cancelling all requests for a url does cancel the cronet request.
48	 * </ul>
49	 */
50	final class ChromiumRequestSerializer {
51	  private static final String TAG = "ChromiumSerializer";
52	
53	  private static final Map<Priority, Integer> GLIDE_TO_CHROMIUM_PRIORITY =
54	      new EnumMap<>(Priority.class);
55	  // Memoized so that all callers can share an instance.
56	  // Suppliers.memoize() is thread safe. See google3/java/com/google/common/base/Suppliers.java
57	  private static final Supplier<Executor> GLIDE_EXECUTOR_SUPPLIER =
58	      Suppliers.memoize(
59	          new Supplier<Executor>() {
60	            @Override
61	            public GlideExecutor get() {
62	              // Allow network operations, but use a single thread. See b/37684357.
63	              return GlideExecutor.newSourceExecutor(
64	                  1 /*threadCount*/, "chromium-serializer", UncaughtThrowableStrategy.DEFAULT);
65	            }
66	          });
67	
68	  private abstract static class PriorityRunnable implements Runnable, Comparable<PriorityRunnable> {
69	
70	    private final int priority;
71	
72	    private PriorityRunnable(Priority priority) {
73	      this.priority = priority.ordinal();
74	    }
75	
76	    @Override
77	    public final int compareTo(PriorityRunnable another) {
78	      if (another.priority > this.priority) {
79	        return -1;
80	      } else if (another.priority < this.priority) {
81	        return 1;
82	      }
83	      return 0;
84	    }
85	  }
86	
87	  static {
88	    GLIDE_TO_CHROMIUM_PRIORITY.put(Priority.IMMEDIATE, UrlRequest.Builder.REQUEST_PRIORITY_HIGHEST);
89	    GLIDE_TO_CHROMIUM_PRIORITY.put(Priority.HIGH, UrlRequest.Builder.REQUEST_PRIORITY_MEDIUM);
90	    GLIDE_TO_CHROMIUM_PRIORITY.put(Priority.NORMAL, UrlRequest.Builder.REQUEST_PRIORITY_LOW);
91	    GLIDE_TO_CHROMIUM_PRIORITY.put(Priority.LOW, UrlRequest.Builder.REQUEST_PRIORITY_LOWEST);
92	  }
