99	  ChromiumRequestSerializer(
100	      CronetRequestFactory requestFactory,
101	      @Nullable DataLogger dataLogger,
102	      @Nullable final GlideExecutor executor) {
103	    this.requestFactory = requestFactory;
104	    this.dataLogger = dataLogger;
105	    if (executor == null) {
106	      this.jobPool = new JobPool(GLIDE_EXECUTOR_SUPPLIER);
107	    } else {
108	      this.jobPool =
109	          new JobPool(
110	              new Supplier<Executor>() {
111	                @Override
112	                public Executor get() {
113	                  return executor;
114	                }
115	              });
116	    }
117	  }
