119	  void startRequest(Priority priority, GlideUrl glideUrl, Listener listener) {
120	    boolean startNewRequest = false;
121	    Job job;
122	    synchronized (this) {
123	      job = jobs.get(glideUrl);
124	      if (job == null) {
125	        startNewRequest = true;
126	        job = jobPool.get(glideUrl);
127	        jobs.put(glideUrl, job);
128	      }
129	      job.addListener(listener);
130	    }
131	
132	    if (startNewRequest) {
133	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
134	        Log.v(TAG, "Fetching image url using cronet" + " url: " + glideUrl);
135	      }
136	      job.priority = priority;
137	      job.request =
138	          requestFactory
139	              .newRequest(
140	                  glideUrl.toStringUrl(),
141	                  GLIDE_TO_CHROMIUM_PRIORITY.get(priority),
142	                  glideUrl.getHeaders(),
143	                  job)
144	              .build();
145	      job.request.start();
146	
147	      // It's possible we will be cancelled between adding the job to the job list and starting the
148	      // corresponding request. We don't want to hold a lock while starting the request, because
149	      // starting the request may block for a while and we need cancellation to happen quickly (it
150	      // happens on the main thread).
151	      if (job.isCancelled) {
152	        job.request.cancel();
153	      }
154	    }
155	  }
