278	                @Override
279	                public void run() {
280	                  onRequestFinished(urlResponseInfo, e, false /*wasCancelled*/, null /*buffer*/);
281	                }
282	              });
283	    }
284	
285	    @Override
286	    public void onCanceled(UrlRequest urlRequest, @Nullable final UrlResponseInfo urlResponseInfo) {
287	      executorSupplier
288	          .get()
289	          .execute(
290	              new PriorityRunnable(priority) {
291	                @Override
292	                public void run() {
293	                  onRequestFinished(
294	                      urlResponseInfo, null /*exception*/, true /*wasCancelled*/, null /*buffer*/);
295	                }
296	              });
297	    }
298	
299	    private void onRequestFinished(
300	        UrlResponseInfo info,
301	        @Nullable CronetException e,
302	        boolean wasCancelled,
303	        ByteBuffer buffer) {
304	      synchronized (ChromiumRequestSerializer.this) {
305	        jobs.remove(glideUrl);
306	      }
307	
308	      Exception exception = getExceptionIfFailed(info, e, wasCancelled);
309	      boolean isSuccess = exception == null && !wasCancelled;
310	
311	      endTimeMs = System.currentTimeMillis();
312	
313	      maybeLogResult(isSuccess, exception, wasCancelled, buffer);
314	      if (isSuccess) {
315	        notifySuccess(buffer);
316	      } else {
317	        notifyFailure(exception);
318	      }
319	
320	      if (dataLogger != null) {
321	        dataLogger.logNetworkData(info, startTime, responseStartTimeMs, endTimeMs);
322	      }
323	      builder = null;
324	
325	      jobPool.put(this);
326	    }
327	
328	    private void notifySuccess(ByteBuffer buffer) {
329	      ByteBuffer toNotify = buffer;
330	      /* Locking here isn't necessary and is potentially dangerous. There's an optimization in
331	       * Glide that avoids re-posting results if the callback onRequestComplete triggers is called
332	       * on the calling thread. If that were ever to happen here (the request is cached in memory?),
333	       * this might block all requests for a while. Locking isn't necessary because the Job is
334	       * removed from the serializer's job set at the beginning of onRequestFinished. After that
335	       * point, whatever thread we're on is the only one that has access to the Job. Subsequent
336	       * requests for the same image would trigger an additional RPC/Job. */
337	      for (int i = 0, size = listeners.size(); i < size; i++) {
338	        Listener listener = listeners.get(i);
339	        listener.onRequestComplete(toNotify);
340	        toNotify = (ByteBuffer) toNotify.asReadOnlyBuffer().position(0);
341	      }
342	    }
343	
344	    private void notifyFailure(Exception exception) {
345	      /* Locking here isn't necessary and is potentially dangerous. There's an optimization in
346	       * Glide that avoids re-posting results if the callback onRequestComplete triggers is called
347	       * on the calling thread. If that were ever to happen here (the request is cached in memory?),
348	       * this might block all requests for a while. Locking isn't necessary because the Job is
349	       * removed from the serializer's job set at the beginning of onRequestFinished. After that
350	       * point, whatever thread we're on is the only one that has access to the Job. Subsequent
351	       * requests for the same image would trigger an additional RPC/Job. */
352	      for (int i = 0, size = listeners.size(); i < size; i++) {
353	        Listener listener = listeners.get(i);
354	        listener.onRequestFailed(exception);
355	      }
356	    }
357	
358	    private void maybeLogResult(
359	        boolean isSuccess, Exception exception, boolean wasCancelled, ByteBuffer buffer) {
360	      if (isSuccess && Log.isLoggable(TAG, Log.VERBOSE)) {
361	        Log.v(
362	            TAG,
363	            "Successfully completed request"
364	                + ", url: "
365	                + glideUrl
366	                + ", duration: "
367	                + (System.currentTimeMillis() - startTime)
368	                + ", file size: "
369	                + (buffer.limit() / 1024)
370	                + "kb");
371	      } else if (!isSuccess && Log.isLoggable(TAG, Log.WARN) && !wasCancelled) {
372	        Log.w(TAG, "Request failed, url: " + glideUrl, exception);
373	      }
374	    }
375	
376	    private void clearListeners() {
377	      synchronized (ChromiumRequestSerializer.this) {
378	        listeners.clear();
379	        request = null;
380	        isCancelled = false;
381	      }
382	    }
383	  }
384	
385	  private class JobPool {
386	    private static final int MAX_POOL_SIZE = 50;
387	    private final ArrayDeque<Job> pool = new ArrayDeque<>();
388	    private final Supplier<Executor> executorSupplier;
389	
390	    public JobPool(Supplier<Executor> executorSupplier) {
391	      this.executorSupplier = executorSupplier;
392	    }
393	
394	    public synchronized Job get(GlideUrl glideUrl) {
395	      Job job = pool.poll();
396	      if (job == null) {
397	        job = new Job(executorSupplier);
398	      }
399	      job.init(glideUrl);
400	      return job;
401	    }
402	
403	    public void put(Job job) {
404	      job.clearListeners();
405	      synchronized (this) {
406	        if (pool.size() < MAX_POOL_SIZE) {
407	          pool.offer(job);
408	        }
409	      }
410	    }
411	  }
412	
413	  interface Listener {
414	    void onRequestComplete(ByteBuffer byteBuffer);
415	
416	    void onRequestFailed(@Nullable Exception e);
417	  }
418	}
