21	/** Utilities for getting ListenableFutures out of Glide. */
22	public final class GlideFutures {
23	
24	  /**
25	   * Preloads the resource for {@code builder} and returns a {@link ListenableFuture} that can be
26	   * used to monitor status.
27	   *
28	   * <p>Shorthand for simply calling {@link #submitAndExecute(RequestManager, RequestBuilder,
29	   * ResourceConsumer, Executor)} with an empty {@code action}.
30	   */
31	  // Wildcard resource types can't be directly instantiated, we don't need to care about the type
32	  // here.
33	  @SuppressWarnings({"rawtypes", "unchecked"})
34	  public static ListenableFuture<Void> preload(
35	      final RequestManager requestManager, RequestBuilder<?> builder, Executor executor) {
36	    return submitAndExecute(
37	        requestManager,
38	        builder,
39	        new ResourceConsumer() {
40	          @Override
41	          public void act(Object resource) {}
42	        },
43	        executor);
44	  }
45	
46	  /**
47	   * Acts on a resource loaded by Glide.
48	   *
49	   * @param <T> The type of resource (Bitmap, Drawable etc).
50	   */
51	  public interface ResourceConsumer<T> {
52	    void act(T resource);
53	  }
54	
55	  /**
56	   * Submits the provided request, performs the provided {@code action} and returns a {@link
57	   * ListenableFuture} that can be used to cancel the request or monitor its status.
58	   *
59	   * <p>Cancellation is best effort and may result in some resources not being returned back to
60	   * Glide's pool. In particular, if the request is cancelled after the resource is loaded by Glide,
61	   * but before {@code action} is run on {@code executor}, the resource will not be returned. We
62	   * have the unfortunate choice between unsafely returning resources to the pool immediately when
63	   * cancel is called while they may still be in use via {@code
64	   * com.google.common.util.concurrent.ClosingFuture} or occasionally failing to return resources to
65	   * the pool. Because failing to return resources to the pool is inefficient, but safe, that's the
66	   * route we've chosen. A more sophisticated implementation may allow us to avoid the resource
67	   * inefficiency.
68	   *
69	   * <p>If you do not need to interact with resource, use {@link #preload(RequestManager,
70	   * RequestBuilder, Executor)}. {@code preload} is more efficient because it knows that the
71	   * resource is never used and can always clear the resource immediately on cancellation, unlike
72	   * this method.
73	   *
74	   * <p>An example usage:
75	   *
76	   * <pre>{@code
77	   *   ListenableFuture<Void> future =
78	   *     submitAndExecute(
79	   *       requestManager,
80	   *       requestBuilder,
81	   *       (bitmap) -> doSomethingWithBitmap(bitmap),
82	   *       backgroundExecutor);
83	   * ;
84	   * }</pre>
85	   *
86	   * @param <T> The type of resource that will be loaded (Bitmap, Drawable, etc).
87	   */
88	  public static <T> ListenableFuture<Void> submitAndExecute(
89	      final RequestManager requestManager,
90	      RequestBuilder<T> requestBuilder,
91	      final ResourceConsumer<T> action,
92	      Executor executor) {
93	    // If the request completes normally, then the target is cleared and the resource is returned.
94	    // If the request fails while loading the image, there's no need to clear.
95	    // If the request fails while calling the action, the target is cleared and the resource is
96	    // returned.
97	    // If the request is cancelled before the resource is loaded, then the resource is returned
98	    // If the request is cancelled after the resource is loaded but before the transform runs,
99	    // then the resource is dropped (but not leaked)
100	    // If the request is cancelled after the transform method starts, then the resource is returned.
101	    return FluentFuture.from(submitInternal(requestBuilder))
102	        .transform(
103	            new Function<TargetAndResult<T>, Void>() {
104	              @Override
105	              public Void apply(TargetAndResult<T> targetAndResult) {
106	                try {
107	                  action.act(targetAndResult.result);
108	                } finally {
109	                  requestManager.clear(targetAndResult.target);
110	                }
111	                return null;
112	              }
113	            },
114	            executor);
115	  }
116	
117	  /**
118	   * Convert a pending load request into a ListenableFuture.
119	   *
120	   * <p>Sample code:
121	   *
122	   * <pre>{@code
123	   * ListenableFuture<File> image =
124	   *     GlideFutures.submit(requestManager.asFile().load(url));
125	   * }</pre>
126	   *
127	   * @param requestBuilder A request builder for the resource to load. It must be tied to an
128	   *     application Glide instance, and must not have a listener set.
129	   * @param <T> The type of resource that will be loaded (Bitmap, Drawable, etc).
130	   */
131	  public static <T> ListenableFuture<T> submit(final RequestBuilder<T> requestBuilder) {
132	    return transformFromTargetAndResult(submitInternal(requestBuilder));
133	  }
134	
135	  private static <T> ListenableFuture<T> transformFromTargetAndResult(
136	      ListenableFuture<TargetAndResult<T>> future) {
137	    return Futures.transform(
138	        future,
139	        new Function<TargetAndResult<T>, T>() {
140	          @Override
141	          public T apply(TargetAndResult<T> input) {
142	            return input.result;
143	          }
144	        },
145	        Executors.directExecutor());
146	  }
147	
148	  private static <T> ListenableFuture<TargetAndResult<T>> submitInternal(
149	      final RequestBuilder<T> requestBuilder) {
150	    GlideFuture<T> future = new GlideFuture<>();
151	    try {
152	      FutureTarget<T> futureTarget = requestBuilder.addListener(future).submit();
153	      future.setFutureTarget(futureTarget);
154	    } catch (RuntimeException e) {
155	      future.setException(e);
156	    }
157	    return future;
158	  }
159	
160	  private static final class GlideFuture<T> extends AbstractFuture<TargetAndResult<T>>
161	      implements RequestListener<T> {
162	    @GuardedBy("this")
163	    @Nullable
164	    private FutureTarget<T> futureTarget;
165	
166	    void setFutureTarget(FutureTarget<T> futureTarget) {
167	      synchronized (this) {
168	        this.futureTarget = futureTarget;
169	      }
170	      if (isCancelled()) {
171	        futureTarget.cancel(wasInterrupted());
172	      }
173	    }
174	
175	    @Override
176	    public boolean set(TargetAndResult<T> value) {
177	      return super.set(value);
178	    }
179	
180	    @Override
181	    public boolean setException(Throwable throwable) {
182	      return super.setException(throwable);
183	    }
184	
185	    @Override
186	    public boolean cancel(boolean mayInterruptIfRunning) {
187	      boolean cancelled = super.cancel(mayInterruptIfRunning);
188	      if (cancelled) {
189	        FutureTarget<T> target;
190	        synchronized (this) {
191	          target = this.futureTarget;
192	        }
193	        if (target != null) {
194	          target.cancel(mayInterruptIfRunning);
195	        }
196	      }
197	      return cancelled;
198	    }
199	
200	    @Override
201	    @Nullable
202	    protected String pendingToString() {
203	      FutureTarget<T> target;
204	      synchronized (this) {
205	        target = this.futureTarget;
206	      }
207	      if (target != null) {
208	        return "activeTarget=[" + target + "]";
209	      }
210	      return null;
211	    }
212	
213	    @Override
214	    public boolean onLoadFailed(
215	        @Nullable GlideException e, Object model, @NonNull Target<T> target, boolean isFirst) {
216	      setException(e != null ? e : new RuntimeException("Unknown error"));
217	      return true;
218	    }
219	
220	    @Override
221	    public boolean onResourceReady(
222	        @NonNull T resource,
223	        @NonNull Object model,
224	        Target<T> target,
225	        @NonNull DataSource dataSource,
226	        boolean isFirst) {
227	      try {
228	        set(new TargetAndResult<>(target, resource));
229	      } catch (Throwable t) {
230	        setException(t);
231	      }
232	      return true;
233	    }
234	  }
235	
236	  private static final class TargetAndResult<T> {
237	    private final Target<T> target;
238	    private final T result;
239	
240	    TargetAndResult(Target<T> target, T result) {
241	      this.target = target;
242	      this.result = result;
243	    }
244	  }
245	
246	  private GlideFutures() {}
247	}
