34	/**
35	 * An {@link com.bumptech.glide.load.ResourceEncoder} that can write {@link
36	 * com.bumptech.glide.load.resource.gif.GifDrawable} to cache.
37	 */
38	public class ReEncodingGifResourceEncoder implements ResourceEncoder<GifDrawable> {
39	
40	  private static final String KEY_ENCODE_TRANSFORMATION =
41	      "com.bumptech.glide.load.resource.gif.GifResourceEncoder.EncodeTransformation";
42	
43	  /**
44	   * A boolean option that, if set to <code>true</code>, causes the fully transformed GIF to be
45	   * written to cache.
46	   *
47	   * <p>Warning - encoding GIFs is slow and often produces larger and less efficient GIFs than the
48	   * originals. Re-encoding may be worth it to decrease the size of very large GIFs.
49	   *
50	   * <p>Defaults to <code>false</code>.
51	   */
52	  // Public API.
53	  @SuppressWarnings("WeakerAccess")
54	  public static final Option<Boolean> ENCODE_TRANSFORMATION =
55	      Option.disk(
56	          KEY_ENCODE_TRANSFORMATION,
57	          false,
58	          new Option.CacheKeyUpdater<Boolean>() {
59	            @Override
60	            public void update(
61	                @NonNull byte[] keyBytes,
62	                @NonNull Boolean value,
63	                @NonNull MessageDigest messageDigest) {
64	              if (value) {
65	                messageDigest.update(keyBytes);
66	              }
67	            }
68	          });
69	
70	  private static final Factory FACTORY = new Factory();
71	  private static final String TAG = "GifEncoder";
72	  private final GifDecoder.BitmapProvider provider;
73	  private final Context context;
74	  private final BitmapPool bitmapPool;
75	  private final Factory factory;
76	
77	  // Public API.
78	  @SuppressWarnings("unused")
79	  public ReEncodingGifResourceEncoder(@NonNull Context context, @NonNull BitmapPool bitmapPool) {
80	    this(context, bitmapPool, FACTORY);
81	  }
82	
83	  @VisibleForTesting
84	  ReEncodingGifResourceEncoder(Context context, BitmapPool bitmapPool, Factory factory) {
85	    this.context = context;
86	    this.bitmapPool = bitmapPool;
87	    provider = new GifBitmapProvider(bitmapPool);
88	    this.factory = factory;
89	  }
90	
91	  @NonNull
92	  @Override
93	  public EncodeStrategy getEncodeStrategy(@NonNull Options options) {
94	    Boolean encodeTransformation = options.get(ENCODE_TRANSFORMATION);
95	    return encodeTransformation != null && encodeTransformation
96	        ? EncodeStrategy.TRANSFORMED
97	        : EncodeStrategy.SOURCE;
98	  }
99	
100	  @Override
101	  public boolean encode(
102	      @NonNull Resource<GifDrawable> resource, @NonNull File file, @NonNull Options options) {
103	    GifDrawable drawable = resource.get();
104	    Transformation<Bitmap> transformation = drawable.getFrameTransformation();
105	    boolean isTransformed = !(transformation instanceof UnitTransformation);
106	    if (isTransformed && options.get(ENCODE_TRANSFORMATION)) {
107	      return encodeTransformedToFile(drawable, file);
108	    } else {
109	      return writeDataDirect(drawable.getBuffer(), file);
110	    }
111	  }
112	
113	  private boolean encodeTransformedToFile(GifDrawable drawable, File file) {
114	    long startTime = LogTime.getLogTime();
115	    OutputStream os = null;
116	    boolean success = false;
117	    try {
118	      os = new BufferedOutputStream(new FileOutputStream(file));
119	      success = encodeTransformedToStream(drawable, os);
120	      os.close();
121	    } catch (IOException e) {
122	      if (Log.isLoggable(TAG, Log.DEBUG)) {
123	        Log.d(TAG, "Failed to encode GIF", e);
124	      }
125	    } finally {
126	      if (os != null) {
127	        try {
128	          os.close();
129	        } catch (IOException e) {
130	          // Ignored.
131	        }
132	      }
133	    }
134	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
135	      Log.v(
136	          TAG,
137	          "Re-encoded GIF with "
138	              + drawable.getFrameCount()
139	              + " frames and "
140	              + drawable.getBuffer().limit()
141	              + " bytes in "
142	              + LogTime.getElapsedMillis(startTime)
143	              + " ms");
144	    }
145	
146	    return success;
147	  }
148	
149	  private boolean encodeTransformedToStream(GifDrawable drawable, OutputStream os) {
150	    Transformation<Bitmap> transformation = drawable.getFrameTransformation();
151	    GifDecoder decoder = decodeHeaders(drawable.getBuffer());
152	    AnimatedGifEncoder encoder = factory.buildEncoder();
153	    if (!encoder.start(os)) {
154	      return false;
155	    }
156	
157	    for (int i = 0; i < decoder.getFrameCount(); i++) {
158	      Bitmap currentFrame = decoder.getNextFrame();
159	      Resource<Bitmap> transformedResource =
160	          getTransformedFrame(currentFrame, transformation, drawable);
161	      try {
162	        if (!encoder.addFrame(transformedResource.get())) {
163	          return false;
164	        }
165	        int currentFrameIndex = decoder.getCurrentFrameIndex();
166	        int delay = decoder.getDelay(currentFrameIndex);
167	        encoder.setDelay(delay);
168	
169	        decoder.advance();
170	      } finally {
171	        transformedResource.recycle();
172	      }
173	    }
174	
175	    return encoder.finish();
176	  }
177	
178	  private boolean writeDataDirect(ByteBuffer data, File file) {
179	    try {
180	      ByteBufferUtil.toFile(data, file);
181	    } catch (IOException e) {
182	      if (Log.isLoggable(TAG, Log.WARN)) {
183	        Log.w(TAG, "Failed to write GIF data", e);
184	      }
185	      return false;
186	    }
187	    return true;
188	  }
189	
190	  private GifDecoder decodeHeaders(ByteBuffer data) {
191	    GifHeaderParser parser = factory.buildParser();
192	    parser.setData(data);
193	    GifHeader header = parser.parseHeader();
194	
195	    GifDecoder decoder = factory.buildDecoder(provider);
196	    decoder.setData(header, data);
197	    decoder.advance();
198	
199	    return decoder;
200	  }
201	
202	  private Resource<Bitmap> getTransformedFrame(
203	      Bitmap currentFrame, Transformation<Bitmap> transformation, GifDrawable drawable) {
204	    // TODO: what if current frame is null?
205	    Resource<Bitmap> bitmapResource = factory.buildFrameResource(currentFrame, bitmapPool);
206	    Resource<Bitmap> transformedResource =
207	        transformation.transform(
208	            context, bitmapResource, drawable.getIntrinsicWidth(), drawable.getIntrinsicHeight());
209	    if (!bitmapResource.equals(transformedResource)) {
210	      bitmapResource.recycle();
211	    }
212	    return transformedResource;
213	  }
214	
215	  @VisibleForTesting
216	  static class Factory {
217	
218	    GifDecoder buildDecoder(GifDecoder.BitmapProvider bitmapProvider) {
219	      return new StandardGifDecoder(bitmapProvider);
220	    }
221	
222	    GifHeaderParser buildParser() {
223	      return new GifHeaderParser();
224	    }
225	
226	    AnimatedGifEncoder buildEncoder() {
227	      return new AnimatedGifEncoder();
228	    }
229	
230	    @NonNull
231	    Resource<Bitmap> buildFrameResource(@NonNull Bitmap bitmap, @NonNull BitmapPool bitmapPool) {
232	      return new BitmapResource(bitmap, bitmapPool);
233	    }
234	  }
235	}
