31	  @GuardedBy("this")
32	  private long maximumSizeBytes;
33	
34	  EvictionManager(
35	      JournaledLruDiskCache diskCache,
36	      File cacheDirectory,
37	      FileSystem fileSystem,
38	      Journal journal,
39	      Looper workLooper,
40	      long maximumSizeBytes,
41	      float slopMultiplier,
42	      long staleEvictionThresholdMs,
43	      Clock clock) {
44	    this.diskCache = diskCache;
45	    this.cacheDirectory = cacheDirectory;
46	    this.fileSystem = fileSystem;
47	    this.journal = journal;
48	    this.workLooper = workLooper;
49	    this.maximumSizeBytes = maximumSizeBytes;
50	    this.clock = clock;
51	    this.staleEvictionThresholdMs = staleEvictionThresholdMs;
52	
53	    evictionSlopBytes =
54	        Math.min(Math.round(maximumSizeBytes * slopMultiplier), MAXIMUM_EVICTION_SLOP);
55	    evictionHandler = new Handler(workLooper, new EvictionCallback());
56	  }
57	
58	  /**
59	   * Sets maximumSizeBytes to a new size.
60	   *
61	   * <p>Must be called on a background thread.
62	   *
63	   * <p>Decreasing the maximumSizeBytes may schedule an eviction if the current cache size exceeds
64	   * the new maximumSizeBytes. Evictions will be scheduled and executed asynchronously. Therefore,
65	   * the eviction will happen based on the latest maximum cache size, not the maximum size at
66	   * scheduling.
67	   */
68	  synchronized void setMaximumSizeBytes(long newMaxSizeBytes) {
69	    long originalMaxBytes = maximumSizeBytes;
70	    maximumSizeBytes = newMaxSizeBytes;
71	    if (newMaxSizeBytes < originalMaxBytes) {
72	      maybeScheduleEviction(newMaxSizeBytes);
73	    }
74	  }
75	
76	  private synchronized long getMaximumSizeBytes() {
77	    return maximumSizeBytes;
78	  }
79	
80	  /**
81	   * Schedules a journal eviction on a work thread if the journal size currently exceeds the allowed
82	   * cache size.
83	   */
84	  void maybeScheduleEviction() {
85	    maybeScheduleEviction(getMaximumSizeBytes());
86	  }
87	
88	  private void maybeScheduleEviction(long maximumSizeBytes) {
89	    if (isEvictionRequired(maximumSizeBytes)) {
90	      evictionHandler.obtainMessage(MessageIds.EVICT).sendToTarget();
91	    }
92	  }
93	
94	  private boolean isEvictionRequired(long maximumSizeBytes) {
95	    return journal.getCurrentSizeBytes() > evictionSlopBytes + maximumSizeBytes;
96	  }
97	
98	  private void evictOnWorkThread() {
99	    if (!Looper.myLooper().equals(workLooper)) {
100	      throw new IllegalStateException(
101	          "Cannot call evictOnWorkThread on thread: " + Thread.currentThread().getName());
102	    }
103	    long maximumSizeBytes = getMaximumSizeBytes();
104	    long staleDateMs = clock.currentTimeMillis() - staleEvictionThresholdMs;
105	    List<String> staleEntriesKeys = journal.getStaleEntries(staleDateMs);
106	    // Writes may queue up a number of eviction messages. After the first one runs, eviction may no
107	    // longer be necessary, so we simply ignore the message.
108	    if (!isEvictionRequired(maximumSizeBytes) && staleEntriesKeys.isEmpty()) {
109	      if (LOG_VERBOSE) {
110	        Log.v(TAG, "Ignoring eviction, not needed");
111	      }
112	      return;
113	    }
114	    if (LOG_DEBUG) {
115	      Log.d(TAG, "Starting eviction on work thread");
116	    }
117	
118	    int successfullyDeletedCount = 0;
119	    int triedToDeleteEntries = staleEntriesKeys.size();
120	    if (!staleEntriesKeys.isEmpty()) {
121	      successfullyDeletedCount += diskCache.delete(staleEntriesKeys).size();
122	    }
123	
124	    long targetSize = maximumSizeBytes - evictionSlopBytes;
125	    if (isEvictionRequired(maximumSizeBytes)) {
126	      long bytesToEvict = journal.getCurrentSizeBytes() - targetSize;
127	      List<String> leastRecentlyUsedKeys = journal.getLeastRecentlyUsed(bytesToEvict);
128	      triedToDeleteEntries += leastRecentlyUsedKeys.size();
129	      successfullyDeletedCount += diskCache.delete(leastRecentlyUsedKeys).size();
130	    }
131	
132	    if (triedToDeleteEntries == 0) {
133	      throw new IllegalStateException("Failed to find entries to evict.");
134	    }
135	
136	    if (LOG_DEBUG) {
137	      Log.d(
138	          TAG,
139	          "Ran eviction"
140	              + ", tried to delete: "
141	              + triedToDeleteEntries
142	              + " entries"
143	              + ", actually deleted: "
144	              + successfullyDeletedCount
145	              + " entries"
146	              + ", target journal : "
147	              + targetSize
148	              + ", journal size: "
149	              + journal.getCurrentSizeBytes()
150	              + ", file size: "
151	              + fileSystem.getDirectorySize(cacheDirectory));
152	    }
153	  }
154	
155	  private class EvictionCallback implements Handler.Callback {
156	    @Override
157	    public boolean handleMessage(Message msg) {
158	      if (msg.what != MessageIds.EVICT) {
159	        return false;
160	      }
161	      evictOnWorkThread();
162	      return true;
163	    }
164	  }
165	}
