2	
3	import androidx.collection.ArrayMap;
4	import com.bumptech.glide.util.LruCache;
5	import java.io.File;
6	import java.util.concurrent.locks.ReentrantReadWriteLock;
7	
8	/**
9	 * Maintains an LRU cache of {@link String} keys to {@link Entry Entrys} where each entry contains a
10	 * read/write lock used to guarantee state and entries that are currently locked are guaranteed not
11	 * to be evicted.
12	 */
13	final class EntryCache {
14	  private final ArrayMap<String, Entry> activeEntries = new ArrayMap<>();
15	  private final LruCache<String, Entry> inactiveEntries = new LruCache<>(6000);
16	
17	  synchronized void clear() {
18	    activeEntries.clear();
19	    inactiveEntries.clearMemory();
20	  }
21	
22	  synchronized Entry get(String key) {
23	    Entry entry = activeEntries.get(key);
24	    if (entry == null) {
25	      entry = inactiveEntries.get(key);
26	      if (entry == null) {
27	        entry = new Entry(key, this);
28	        activeEntries.put(key, entry);
29	      }
30	    }
31	    return entry;
32	  }
33	
34	  private synchronized void removeFromActive(Entry entry) {
35	    activeEntries.remove(entry.key);
36	    inactiveEntries.put(entry.key, entry);
37	  }
38	
39	  private synchronized void addToActive(Entry entry) {
40	    inactiveEntries.remove(entry.key);
41	    activeEntries.put(entry.key, entry);
42	  }
43	
44	  static final class Entry {
45	    private ReentrantReadWriteLock readWriteLock = new ReentrantReadWriteLock();
46	    private final String key;
47	    private final EntryCache cache;
48	
49	    private int lockCount;
50	    private State state = State.UNKNOWN;
51	    private File file;
52	
53	    Entry(String key, EntryCache cache) {
54	      this.key = key;
55	      this.cache = cache;
56	    }
57	
58	    File getFile() {
59	      return file;
60	    }
61	
62	    boolean isStateKnown() {
63	      return state != State.UNKNOWN;
64	    }
65	
66	    boolean isPresent() {
67	      return state == State.PRESENT;
68	    }
69	
70	    void setPresent(File file) {
71	      this.file = file;
72	      state = State.PRESENT;
73	    }
74	
75	    void setUnknown() {
76	      state = State.UNKNOWN;
77	    }
78	
79	    void setNotPresent() {
80	      state = State.NOT_PRESENT;
81	    }
82	
83	    void acquireReadLock() {
84	      maybeSetActive();
85	      readWriteLock.readLock().lock();
86	    }
87	
88	    void releaseReadLock() {
89	      ReentrantReadWriteLock lock = readWriteLock;
90	      maybeSetInactive();
91	      lock.readLock().unlock();
92	    }
93	
94	    void acquireWriteLock() {
95	      maybeSetActive();
96	      readWriteLock.writeLock().lock();
97	    }
98	
99	    void releaseWriteLock() {
100	      ReentrantReadWriteLock lock = readWriteLock;
101	      maybeSetInactive();
102	      lock.writeLock().unlock();
103	    }
104	
105	    private synchronized void maybeSetActive() {
106	      lockCount++;
107	      if (lockCount == 1) {
108	        cache.addToActive(this);
109	        readWriteLock = new ReentrantReadWriteLock();
110	      }
111	    }
112	
113	    private synchronized void maybeSetInactive() {
114	      lockCount--;
115	      if (lockCount == 0) {
116	        cache.removeFromActive(this);
117	        readWriteLock = null;
118	      }
119	    }
120	
121	    private enum State {
122	      UNKNOWN,
123	      PRESENT,
124	      NOT_PRESENT,
125	    }
126	  }
127	}
