14	import java.util.concurrent.atomic.AtomicLong;
15	
16	final class SizeJournal {
17	  private static final String UPDATE_CACHE_SIZE_SQL =
18	      "UPDATE "
19	          + SizeTable.TABLE_NAME
20	          + " SET "
21	          + SizeTable.Columns.SIZE
22	          + " = "
23	          + SizeTable.Columns.SIZE
24	          + " + ?";
25	  private static final int UPDATE_CACHE_SIZE_SIZE_INCREMENT_IDX = 1;
26	
27	  private static final String CONTAINS_SIZE_QUERY = "SELECT COUNT(*) FROM " + SizeTable.TABLE_NAME;
28	  private static final String CACHE_SIZE_QUERY =
29	      "SELECT " + SizeTable.Columns.SIZE + " FROM " + SizeTable.TABLE_NAME;
30	  private final AtomicLong size = new AtomicLong();
31	  private final SqliteStatementPool updateCacheSizePool;
32	  private final Pool<SizeSQLiteTransactionListener> sizeListenerPool =
33	      FactoryPools.threadSafe(
34	          /* size= */ 20,
35	          new FactoryPools.Factory<SizeSQLiteTransactionListener>() {
36	            @Override
37	            public SizeSQLiteTransactionListener create() {
38	              return new SizeSQLiteTransactionListener();
39	            }
40	          },
41	          new Resetter<SizeSQLiteTransactionListener>() {
42	            @Override
43	            public void reset(@NonNull SizeSQLiteTransactionListener object) {
44	              object.clear();
45	            }
46	          });
47	
48	  private final DiskCacheDbHelper dbHelper;
49	
50	  SizeJournal(DiskCacheDbHelper dbHelper) {
51	    this.dbHelper = dbHelper;
52	    updateCacheSizePool = new SqliteStatementPool(dbHelper);
53	  }
54	
55	  void open() {
56	    SQLiteDatabase db = dbHelper.getReadableDatabase();
57	    boolean containsSize =
58	        0 != DatabaseUtils.longForQuery(db, CONTAINS_SIZE_QUERY, null /*selectionArgs*/);
59	    final long currentSize;
60	    if (!containsSize) {
61	      ContentValues values = new ContentValues();
62	      values.put(SizeTable.Columns.SIZE, 0);
63	      db.insert(SizeTable.TABLE_NAME, null /*nullColumnHack*/, values);
64	      currentSize = 0;
65	    } else {
66	      currentSize = DatabaseUtils.longForQuery(db, CACHE_SIZE_QUERY, null /*selectionArgs*/);
67	    }
68	    size.set(currentSize);
69	  }
70	
71	  void clearInTransaction() {
72	    SQLiteDatabase db = dbHelper.getReadableDatabase();
73	    db.delete(SizeTable.TABLE_NAME, null /*whereClause*/, null /*whereArgs*/);
74	    size.set(0);
75	  }
76	
77	  long getCacheSizeBytes() {
78	    return size.get();
79	  }
80	
81	  SizeSQLiteTransactionListener prepareSizeTransaction() {
82	    SizeSQLiteTransactionListener result = sizeListenerPool.acquire();
83	    if (result == null) {
84	      result = new SizeSQLiteTransactionListener();
85	    }
86	    return result;
87	  }
88	
89	  void endSizeTransaction(SizeSQLiteTransactionListener listener) {
90	    listener.clear();
91	    sizeListenerPool.release(listener);
92	  }
93	
94	  void decrementSizeInTransaction(SizeSQLiteTransactionListener sizeListener, long decrementBy) {
95	    incrementSizeInTransaction(sizeListener, -decrementBy);
96	  }
97	
98	  void incrementSizeInTransaction(SizeSQLiteTransactionListener sizeListener, long incrementBy) {
99	    sizeListener.updatedSize = incrementBy;
100	
101	    SQLiteStatement updateCacheSizeStatement = updateCacheSizePool.obtain(UPDATE_CACHE_SIZE_SQL);
102	    try {
103	      updateCacheSizeStatement.bindLong(UPDATE_CACHE_SIZE_SIZE_INCREMENT_IDX, incrementBy);
104	      updateCacheSizeStatement.executeUpdateDelete();
105	      size.addAndGet(incrementBy);
106	    } finally {
107	      updateCacheSizePool.offer(UPDATE_CACHE_SIZE_SQL, updateCacheSizeStatement);
108	    }
109	  }
110	
111	  /** A listener that reverts size changes upon transaction failure. */
112	  final class SizeSQLiteTransactionListener implements SQLiteTransactionListener, Poolable {
113	    private long updatedSize;
114	
115	    void clear() {
116	      updatedSize = 0;
117	    }
118	
119	    @Override
120	    public void onBegin() {}
121	
122	    @Override
123	    public void onCommit() {}
124	
125	    @Override
126	    public void onRollback() {
127	      // Revert the increment of size on transaction failure.
128	      size.addAndGet(-updatedSize);
129	    }
130	
131	    @NonNull
132	    @Override
133	    public StateVerifier getVerifier() {
134	      return StateVerifier.newInstance();
135	    }
136	  }
137	}
