33	   * request.read(builder.getNextBuffer(buffer)); } }
34	   */
35	  public static final class Builder {
36	    private ArrayDeque<ByteBuffer> buffers = new ArrayDeque<>();
37	    private RuntimeException whenClosed;
38	
39	    private Builder() {}
40	
41	    /** Returns the next buffer to write data into. */
42	    public ByteBuffer getNextBuffer(ByteBuffer lastBuffer) {
43	      if (buffers == null) {
44	        throw new RuntimeException(whenClosed);
45	      }
46	      if (lastBuffer != buffers.peekLast()) {
47	        buffers.addLast(lastBuffer);
48	      }
49	      if (lastBuffer.hasRemaining()) {
50	        return lastBuffer;
51	      } else {
52	        return ByteBuffer.allocateDirect(DEFAULT_BUFFER_SIZE);
53	      }
54	    }
55	
56	    /** Returns a ByteBuffer heuristically sized to hold the whole response body. */
57	    public ByteBuffer getFirstBuffer(UrlResponseInfo info) {
58	      // Security note - a malicious server could attempt to exhaust client memory by sending
59	      // down a Content-Length of a very large size, which we would eagerly allocate without
60	      // the server having to actually send those bytes. This isn't considered to be an
61	      // issue, because that same malicious server could use our transparent gzip to force us
62	      // to allocate 1032 bytes per byte sent by the server.
63	      return ByteBuffer.allocateDirect((int) Math.min(bufferSizeHeuristic(info), 524288));
64	    }
65	
66	    @SuppressWarnings("checkstyle:UnnecessaryParentheses") // Readability
67	    private static long bufferSizeHeuristic(UrlResponseInfo info) {
68	      final Map<String, List<String>> headers = info.getAllHeaders();
69	      if (headers.containsKey(CONTENT_LENGTH)) {
70	        long contentLength = Long.parseLong(headers.get(CONTENT_LENGTH).get(0));
71	        boolean isCompressed =
72	            !headers.containsKey(CONTENT_ENCODING)
73	                || (headers.get(CONTENT_ENCODING).size() == 1
74	                    && "identity".equals(headers.get(CONTENT_ENCODING).get(0)));
75	        if (isCompressed) {
76	          // We have to guess at the uncompressed size. In the future, consider guessing a
77	          // compression ratio based on the content-type and content-encoding. For now,
78	          // assume 2.
79	          return 2 * contentLength;
80	        } else {
81	          // In this case, we know exactly how many bytes we're going to get, so we can
82	          // size our buffer perfectly. However, we still have to call read() for the last time,
83	          // even when we know there shouldn't be any more bytes coming. To avoid allocating another
84	          // buffer for that case, add one more byte than we really need.
85	          return contentLength + 1;
86	        }
87	      } else {
88	        // No content-length. This means we're either being sent a chunked response, or the
89	        // java stack stripped content length because of transparent gzip. In either case we really
90	        // have no idea, and so we fall back to a reasonable guess.
91	        return DEFAULT_BUFFER_SIZE;
92	      }
93	    }
94	
95	    public BufferQueue build() {
96	      whenClosed = new RuntimeException();
97	      final ArrayDeque<ByteBuffer> buffers = this.buffers;
98	      this.buffers = null;
99	      return new BufferQueue(buffers);
100	    }
101	  }
102	
103	  private BufferQueue(Queue<ByteBuffer> buffers) {
104	    this.buffers = buffers;
105	    for (ByteBuffer buffer : this.buffers) {
106	      buffer.flip();
107	    }
108	  }
109	
110	  /** Returns the response body as a single contiguous buffer. */
111	  public ByteBuffer coalesceToBuffer() {
112	    markCoalesced();
113	    if (buffers.size() == 0) {
114	      return ByteBuffer.allocateDirect(0);
115	    } else if (buffers.size() == 1) {
116	      return buffers.remove();
117	    } else {
118	      int size = 0;
119	      for (ByteBuffer buffer : buffers) {
120	        size += buffer.remaining();
121	      }
122	      ByteBuffer result = ByteBuffer.allocateDirect(size);
123	      while (!buffers.isEmpty()) {
124	        result.put(buffers.remove());
125	      }
126	      result.flip();
127	      return result;
128	    }
129	  }
130	
131	  private void markCoalesced() {
132	    if (!isCoalesced.compareAndSet(false, true)) {
133	      throw new IllegalStateException("This BufferQueue has already been consumed");
134	    }
135	  }
136	}
