2	
3	import android.os.Handler;
4	import android.os.Looper;
5	import android.os.Message;
6	import java.io.File;
7	import java.io.FilenameFilter;
8	import java.util.List;
9	
10	/** Finds and cleans up failed writes and deletes on the work thread. */
11	final class RecoveryManager {
12	
13	  private final JournaledLruDiskCache diskCache;
14	  private final Journal journal;
15	  private final File diskCacheDir;
16	  private final Looper workLooper;
17	  private final Handler recoveryHandler;
18	
19	  RecoveryManager(
20	      JournaledLruDiskCache diskCache, File diskCacheDir, Journal journal, Looper workLooper) {
21	    this.diskCache = diskCache;
22	    this.journal = journal;
23	    this.diskCacheDir = diskCacheDir;
24	    this.workLooper = workLooper;
25	
26	    recoveryHandler = new Handler(workLooper, new RecoveryCallback());
27	  }
28	
29	  void triggerRecovery() {
30	    recoveryHandler.obtainMessage(MessageIds.RECOVER).sendToTarget();
31	  }
32	
33	  private void runRecoveryOnWorkThread() {
34	    if (!Looper.myLooper().equals(workLooper)) {
35	      throw new IllegalStateException(
36	          "Cannot run recovery on a thread other than the work" + " thread!");
37	    }
38	    recoverPartialWrites();
39	    recoverPartialDeletes();
40	  }
41	
42	  private void recoverPartialDeletes() {
43	    List<String> pendingDeleteKeys = journal.getPendingDeleteKeys();
44	    diskCache.delete(pendingDeleteKeys);
45	  }
46	
47	  private void recoverPartialWrites() {
48	    File[] partialWrites =
49	        diskCacheDir.listFiles(
50	            new FilenameFilter() {
51	              @Override
52	              public boolean accept(File dir, String filename) {
53	                return filename.endsWith(JournaledLruDiskCache.TEMP_FILE_INDICATOR);
54	              }
55	            });
56	    if (partialWrites != null) {
57	      for (File file : partialWrites) {
58	        diskCache.recoverPartialWrite(file);
59	      }
60	    }
61	  }
62	
63	  private class RecoveryCallback implements Handler.Callback {
64	
65	    @Override
66	    public boolean handleMessage(Message msg) {
67	      if (msg.what != MessageIds.RECOVER) {
68	        return false;
69	      }
70	      runRecoveryOnWorkThread();
71	      return true;
72	    }
73	  }
74	}
