2	
3	import android.database.sqlite.SQLiteOpenHelper;
4	import android.database.sqlite.SQLiteStatement;
5	import java.util.ArrayDeque;
6	import java.util.HashMap;
7	import java.util.Map;
8	import java.util.Queue;
9	
10	final class SqliteStatementPool {
11	  private static final int MAX_SIZE = 10;
12	
13	  private final Map<String, Queue<SQLiteStatement>> pool = new HashMap<>();
14	  private final SQLiteOpenHelper dbHelper;
15	
16	  SqliteStatementPool(SQLiteOpenHelper dbHelper) {
17	    this.dbHelper = dbHelper;
18	  }
19	
20	  SQLiteStatement obtain(String sql) {
21	    SQLiteStatement statement = null;
22	    synchronized (pool) {
23	      Queue<SQLiteStatement> queueForSql = pool.get(sql);
24	      if (queueForSql != null) {
25	        statement = queueForSql.poll();
26	      }
27	    }
28	    if (statement == null) {
29	      statement = dbHelper.getWritableDatabase().compileStatement(sql);
30	    }
31	    return statement;
32	  }
33	
34	  void offer(String sql, SQLiteStatement statement) {
35	    statement.clearBindings();
36	    synchronized (pool) {
37	      Queue<SQLiteStatement> queueForSql = pool.get(sql);
38	      if (queueForSql == null) {
39	        queueForSql = new ArrayDeque<>(MAX_SIZE);
40	        pool.put(sql, queueForSql);
41	      }
42	      if (queueForSql.size() < MAX_SIZE) {
43	        queueForSql.offer(statement);
44	      }
45	    }
46	  }
47	}
