12	import com.bumptech.glide.load.resource.bitmap.Downsampler;
13	import com.bumptech.glide.util.Preconditions;
14	import java.nio.ByteBuffer;
15	import javax.annotation.Nullable;
16	import org.aomedia.avif.android.AvifDecoder;
17	import org.aomedia.avif.android.AvifDecoder.Info;
18	
19	/** A Glide {@link ResourceDecoder} capable of decoding Avif images. */
20	public final class AvifByteBufferBitmapDecoder implements ResourceDecoder<ByteBuffer, Bitmap> {
21	  private static final String TAG = "AvifBitmapDecoder";
22	
23	  private final BitmapPool bitmapPool;
24	
25	  public AvifByteBufferBitmapDecoder(BitmapPool bitmapPool) {
26	    this.bitmapPool = Preconditions.checkNotNull(bitmapPool);
27	  }
28	
29	  private ByteBuffer maybeCopyBuffer(ByteBuffer source) {
30	    // Native calls can only access ByteBuffer if isDirect() is true. Otherwise, we would have to
31	    // make a copy into a direct ByteBuffer.
32	    if (source.isDirect()) {
33	      return source;
34	    }
35	    ByteBuffer sourceCopy = ByteBuffer.allocateDirect(source.remaining());
36	    sourceCopy.put(source);
37	    sourceCopy.flip();
38	    return sourceCopy;
39	  }
40	
41	  @Override
42	  @Nullable
43	  public Resource<Bitmap> decode(ByteBuffer source, int width, int height, Options options) {
44	    ByteBuffer sourceCopy = maybeCopyBuffer(source);
45	    Info info = new Info();
46	    if (!AvifDecoder.getInfo(sourceCopy, sourceCopy.remaining(), info)) {
47	      if (Log.isLoggable(TAG, Log.ERROR)) {
48	        Log.e(TAG, "Requested to decode byte buffer which cannot be handled by AvifDecoder");
49	      }
50	      return null;
51	    }
52	    Bitmap.Config config;
53	    if (options.get(Downsampler.DECODE_FORMAT) == DecodeFormat.PREFER_RGB_565) {
54	      config = Config.RGB_565;
55	    } else {
56	      config = (info.depth == 8) ? Config.ARGB_8888 : Config.RGBA_F16;
57	    }
58	    Bitmap bitmap = bitmapPool.get(info.width, info.height, config);
59	    if (!AvifDecoder.decode(sourceCopy, sourceCopy.remaining(), bitmap)) {
60	      if (Log.isLoggable(TAG, Log.ERROR)) {
61	        Log.e(TAG, "Failed to decode ByteBuffer as Avif.");
62	      }
63	      bitmapPool.put(bitmap);
64	      return null;
65	    }
66	    return BitmapResource.obtain(bitmap, bitmapPool);
67	  }
68	
69	  @Override
70	  public boolean handles(ByteBuffer source, Options options) {
71	    return AvifDecoder.isAvifImage(maybeCopyBuffer(source));
72	  }
73	}
