8	
9	/**
10	 * Converts {@link androidx.recyclerview.widget.RecyclerView.OnScrollListener} events to {@link
11	 * AbsListView} scroll events.
12	 *
13	 * <p>Requires that the recycler view be using a {@link LinearLayoutManager} subclass.
14	 */
15	// Public API.
16	@SuppressWarnings("WeakerAccess")
17	public final class RecyclerToListViewScrollListener extends RecyclerView.OnScrollListener {
18	  public static final int UNKNOWN_SCROLL_STATE = Integer.MIN_VALUE;
19	  private final AbsListView.OnScrollListener scrollListener;
20	  private int lastFirstVisible = -1;
21	  private int lastVisibleCount = -1;
22	  private int lastItemCount = -1;
23	
24	  public RecyclerToListViewScrollListener(@NonNull AbsListView.OnScrollListener scrollListener) {
25	    this.scrollListener = scrollListener;
26	  }
27	
28	  @Override
29	  public void onScrollStateChanged(RecyclerView recyclerView, int newState) {
30	    int listViewState;
31	    switch (newState) {
32	      case RecyclerView.SCROLL_STATE_DRAGGING:
33	        listViewState = ListView.OnScrollListener.SCROLL_STATE_TOUCH_SCROLL;
34	        break;
35	      case RecyclerView.SCROLL_STATE_IDLE:
36	        listViewState = ListView.OnScrollListener.SCROLL_STATE_IDLE;
37	        break;
38	      case RecyclerView.SCROLL_STATE_SETTLING:
39	        listViewState = ListView.OnScrollListener.SCROLL_STATE_FLING;
40	        break;
41	      default:
42	        listViewState = UNKNOWN_SCROLL_STATE;
43	    }
44	
45	    scrollListener.onScrollStateChanged(null /*view*/, listViewState);
46	  }
47	
48	  @Override
49	  public void onScrolled(RecyclerView recyclerView, int dx, int dy) {
50	    LinearLayoutManager layoutManager = (LinearLayoutManager) recyclerView.getLayoutManager();
51	
52	    int firstVisible = layoutManager.findFirstVisibleItemPosition();
53	    int visibleCount = Math.abs(firstVisible - layoutManager.findLastVisibleItemPosition());
54	    int itemCount = recyclerView.getAdapter().getItemCount();
55	
56	    if (firstVisible != lastFirstVisible
57	        || visibleCount != lastVisibleCount
58	        || itemCount != lastItemCount) {
59	      scrollListener.onScroll(null, firstVisible, visibleCount, itemCount);
60	      lastFirstVisible = firstVisible;
61	      lastVisibleCount = visibleCount;
62	      lastItemCount = itemCount;
63	    }
64	  }
65	}
