3	import android.content.Context;
4	import org.chromium.net.CronetEngine;
5	
6	/**
7	 * Class controlling singleton instance of the CronetEngine. Ensures at most one instance of the
8	 * CronetEngine is created.
9	 */
10	// NOTE: This is a standalone class and not a memoized supplier as the CronetEngine creations
11	// requires a parameter, namedly a Context reference.
12	public final class CronetEngineSingleton {
13	
14	  // non instantiable
15	  private CronetEngineSingleton() {}
16	
17	  private static volatile CronetEngine cronetEngineSingleton;
18	
19	  public static CronetEngine getSingleton(Context context) {
20	
21	    // Lazily create the engine.
22	    if (cronetEngineSingleton == null) {
23	      synchronized (CronetEngineSingleton.class) {
24	        // have to re-check since this might have changed before synchronization, but we don't
25	        // want to synchronize just to check for null.
26	        if (cronetEngineSingleton == null) {
27	          cronetEngineSingleton = createEngine(context);
28	        }
29	      }
30	    }
31	
32	    return cronetEngineSingleton;
33	  }
34	
35	  private static CronetEngine createEngine(Context context) {
36	    return new CronetEngine.Builder(context)
37	        .enableHttpCache(CronetEngine.Builder.HTTP_CACHE_DISABLED, 0)
38	        .enableHttp2(true)
39	        .enableQuic(false)
40	        .build();
41	  }
42	}
