3	import com.google.common.base.Supplier;
4	import java.util.Map;
5	import java.util.concurrent.Executor;
6	import org.chromium.net.CronetEngine;
7	import org.chromium.net.UrlRequest;
8	
9	/** Default implementation for building cronet requests. */
10	public final class CronetRequestFactoryImpl implements CronetRequestFactory {
11	
12	  private final Supplier<CronetEngine> cronetEngineGetter;
13	
14	  public CronetRequestFactoryImpl(Supplier<CronetEngine> cronetEngineGetter) {
15	    this.cronetEngineGetter = cronetEngineGetter;
16	  }
17	
18	  @Override
19	  public UrlRequest.Builder newRequest(
20	      String url, int requestPriority, Map<String, String> headers, UrlRequest.Callback listener) {
21	    CronetEngine engine = cronetEngineGetter.get();
22	    UrlRequest.Builder builder =
23	        engine.newUrlRequestBuilder(
24	            url,
25	            listener,
26	            new Executor() {
27	              @Override
28	              public void execute(Runnable runnable) {
29	                runnable.run();
30	              }
31	            });
32	    builder.allowDirectExecutor();
33	    builder.setPriority(requestPriority);
34	    for (Map.Entry<String, String> header : headers.entrySet()) {
35	      // Cronet owns the Accept-Encoding header and user agent
36	      String key = header.getKey();
37	      if ("Accept-Encoding".equalsIgnoreCase(key) || "User-Agent".equalsIgnoreCase(key)) {
38	        continue;
39	      }
40	      builder.addHeader(key, header.getValue());
41	    }
42	    return builder;
43	  }
44	}
