30	        ByteBuffer.class,
31	        BitmapDrawable.class,
32	        new BitmapDrawableDecoder<>(context.getResources(), byteBufferBitmapDecoder));
33	    AvifStreamBitmapDecoder streamBitmapDecoder =
34	        new AvifStreamBitmapDecoder(
35	            registry.getImageHeaderParsers(), byteBufferBitmapDecoder, glide.getArrayPool());
36	    registry.prepend(Registry.BUCKET_BITMAP, InputStream.class, Bitmap.class, streamBitmapDecoder);
37	    registry.prepend(
38	        Registry.BUCKET_BITMAP_DRAWABLE,
39	        InputStream.class,
